export interface Project {
  id: string;
  name: string;
  ministry: string;
  sector: string;
  location: string;
  agency: string;
  costApproved: string;
  costRevised: string;
  costExpenditure: string;
  costOverrunPct: string;
  progressPhysical: number;
  progressPhysicalTarget: number;
  progressFinancial: number;
  expectedCompletion: string;
  originalCompletion: string;
  startDate: string;
  phase: string;
  type: string;
scheduleStatus: 'DELAYED' | 'ON TRACK' | 'CRITICAL' | 'IN PROGRESS' | 'IN REVIEW';
scheduleExtensionMonths?: number | string;
delayDays?: number;
sourceReport?: string;
asOfDate?: string;
  costLabel: string;
  costSubtext: string;
  riskScore: number; // 0 to 100
  riskLevel: 'Low' | 'Medium' | 'High' | 'Critical';
  description: string;
  costRisk: number;
  timeRisk: number;
  implRisk: number;
  overallRisk: number;
}

export interface ProjectMilestone {
  id: number;
  name: string;
  target_date?: string;
  actual_date?: string;
  status: string;
  delay_months?: number;
}

export interface ProjectBenchmark {
  project_id: string;
  project_name: string;
  sector_name: string;
  cost_benchmark: Array<{ label: string; projectVal: string; avg: string; benchmark: string; isAlert?: boolean }>;
  delay_benchmark: Array<{ label: string; projectVal: string; avg: string; benchmark: string; isAlert?: boolean }>;
  tech_benchmark: Array<{ label: string; projectVal: string; avg: string; benchmark: string; isAlert?: boolean }>;
  recommendation: string;
}

export function getProjectDisplayStatus(p: {
  scheduleStatus?: string;
  riskLevel?: string;
  riskScore?: number;
  progressPhysical?: number;
}): 'CRITICAL' | 'DELAYED' | 'IN REVIEW' | 'ON TRACK' {
  if (p.scheduleStatus === 'CRITICAL' || p.riskLevel === 'Critical' || (p.riskScore !== undefined && p.riskScore >= 75)) {
    return 'CRITICAL';
  }
  const stat = (p.scheduleStatus || '').toUpperCase();
  if (stat.includes('CRIT') || stat.includes('OVERDUE')) {
    return 'CRITICAL';
  }
  if (stat.includes('DELAY') || stat.includes('EXTEND')) {
    return 'DELAYED';
  }
  if (
    stat === 'IN REVIEW' ||
    stat === 'IN PROGRESS' ||
    stat.includes('REVIEW') ||
    stat.includes('PROGRESS') ||
    stat.includes('MONITOR') ||
    (stat === 'ON TRACK' && (p.progressPhysical ?? 0) > 0 && (p.progressPhysical ?? 0) < 100 && (((p.riskScore ?? 0) >= 25) || p.riskLevel === 'Medium'))
  ) {
    return 'IN REVIEW';
  }
  return 'ON TRACK';
}

